it('does not repeat repository or interview subviews as global menu entries', () => {
  render(<WorkspaceShell active="interview"><main>Conversation</main></WorkspaceShell>)
  const nav = desktopNavigation()
  expect(nav.getAllByRole('link', { name: 'Interviews' })).toHaveLength(1)
  expect(nav.queryByRole('link', { name: 'Mock Lab' })).toBeNull()
  expect(nav.queryByRole('link', { name: 'Feedback' })).toBeNull()
  expect(nav.queryByRole('link', { name: 'Repository' })).toBeNull()
  const hrefs = nav.getAllByRole('link').map(link => link.getAttribute('href'))
  expect(new Set(hrefs).size).toBe(hrefs.length)
})

